public class InvertedIndex {
    private final Map<String, Set<Long>> index = new ConcurrentHashMap<>();

    public void addDocument(long docId, String content) {
        String[] tokens = content.toLowerCase().split("\\W+");
        for (String token : tokens) {
            index.computeIfAbsent(token, k -> ConcurrentHashMap.newKeySet()).add(docId);
        }
    }

    public Set<Long> search(String query) {
        return index.getOrDefault(query.toLowerCase(), Collections.emptySet());
    }
}
